// js
const work = get(ctx, 'work', {});
return ['STANDARD', ''].includes(get(ctx.subject.employment.terms, 'statutory_work_category', '')) &&
	get(ctx.subject.employment.terms.rate, 'unit', 'MONTHLY') === 'MONTHLY' &&
	get(work, 'overtime_hours', 0) > 0;

conversion:
// js
const work = get(ctx, 'work', {});
const terms = ctx.subject.employment.terms;
const fixed = ctx.lookup.wage_base_allowances.reduce(
	(total, code) => total + get(terms, `allowances.${code}.amount`, 0),
	0
);
const wage = get(terms, 'rate.amount', 0) + fixed;
return get(work, 'overtime_hours', 0) * ctx.lookup.factor * wage / ctx.lookup.monthly_divisor / ctx.lookup.daily_hours;

