const review = get(
	ctx.subject.employment.employee_extension_data,
	'term_facts.comprehensive_overtime_review',
	null
);
const from = ctx.run.salary_coverage.from;
const to = ctx.run.salary_coverage.to;
return get(ctx.subject.employment.terms, 'statutory_work_category', '') === 'COMPREHENSIVE' &&
	get(ctx.subject.employment.terms.rate, 'unit', 'MONTHLY') === 'MONTHLY' &&
	review != null &&
	review.month === from.slice(0, 7) &&
	review.reference !== '' &&
	review.settlement_on >= from &&
	review.settlement_on <= to &&
	Number(review.excess_nonholiday_hours) > 0;

